     1	const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
     2	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
     3	
     4	/** Formats a date as an ISO date (YYYY-MM-DD) using the browser's local calendar. */
     5	export function toIsoDate(date: Date): string {
     6	  const year = String(date.getFullYear()).padStart(4, '0');
     7	  const month = String(date.getMonth() + 1).padStart(2, '0');
     8	  const day = String(date.getDate()).padStart(2, '0');
     9	  return `${year}-${month}-${day}`;
    10	}
    11	
    12	/** Parses a YYYY-MM-DD string into a local midnight Date; returns null for anything that is not a real calendar date. */
    13	export function parseIsoDate(value: string | null | undefined): Date | null {
    14	  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    15	    return null;
    16	  }
    17	  const [year, month, day] = value.split('-').map(Number);
    18	  const date = new Date(year, month - 1, day);
    19	  if (toIsoDate(date) !== value) {
    20	    return null;
    21	  }
    22	  return date;
    23	}
    24	
    25	/** Local midnight of the given date. */
    26	export function startOfDay(date: Date): Date {
    27	  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
    28	}
    29	
    30	/** Returns the date `days` days after `date`. */
    31	export function addDays(date: Date, days: number): Date {
    32	  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
    33	}
    34	
    35	/** English full weekday name, e.g. "Tuesday". */
    36	export function weekdayName(date: Date): string {
    37	  return WEEKDAYS[date.getDay()];
    38	}
    39	
    40	/** Show date as `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
    41	export function formatShowDate(date: Date, time: string): string {
    42	  return `${weekdayName(date)} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
    43	}
