     1	import { Injectable, inject } from '@angular/core';
     2	import { ActivatedRouteSnapshot, CanActivateFn, Router } from '@angular/router';
     3	
     4	/**
     5	 * The booking in progress (section 3.1). `seats` holds seat identifiers; a couch contributes
     6	 * both of its identifiers.
     7	 */
     8	/** The values typed into the checkout form (section 7.1). */
     9	export interface CheckoutValues {
    10	  firstName: string;
    11	  lastName: string;
    12	  email: string;
    13	  confirmEmail: string;
    14	  phone: string;
    15	  terms: boolean;
    16	}
    17	
    18	export interface Booking {
    19	  screeningId: number;
    20	  seats: string[];
    21	  /** The checkout form values as last typed; absent until the form has been changed. */
    22	  checkout?: CheckoutValues;
    23	  /** Set once the booking is paid: the customer's email address (section 3.1). */
    24	  paid?: { email: string };
    25	}
    26	
    27	/** One line of the summary: a single seat or a couch (section 6). */
    28	export interface Ticket {
    29	  /** Seat identifiers the ticket occupies: one for a seat, two for a couch. */
    30	  ids: string[];
    31	  row: number;
    32	  /** The column number of a seat, or `Couch <a>-<b>`. */
    33	  seat: string;
    34	  /** Price in PLN. */
    35	  price: number;
    36	}
    37	
    38	const STORAGE_KEY = 'cinescope.booking';
    39	const COUCH_ROW = 15;
    40	const COUCH_PRICE = 89;
    41	const SEAT_ID_PATTERN = /^R(\d+)C(\d+)$/;
    42	
    43	function seatId(row: number, column: number): string {
    44	  return `R${row}C${column}`;
    45	}
    46	
    47	function parseSeatId(id: string): { row: number; column: number } | null {
    48	  const match = SEAT_ID_PATTERN.exec(id);
    49	  return match ? { row: Number(match[1]), column: Number(match[2]) } : null;
    50	}
    51	
    52	/** Price of one seat in the given row (section 5.4). */
    53	function seatPrice(row: number): number {
    54	  if (row <= 5) {
    55	    return 25;
    56	  }
    57	  if (row <= 10) {
    58	    return 32;
    59	  }
    60	  return 39;
    61	}
    62	
    63	/** Formats an amount as the price label, e.g. `25.00 PLN`. */
    64	export function formatPrice(amount: number): string {
    65	  return `${amount.toFixed(2)} PLN`;
    66	}
    67	
    68	/** The summary lines of a set of seat identifiers, ordered by row and then by column. */
    69	export function ticketsFor(seatIds: readonly string[]): Ticket[] {
    70	  const seats = seatIds
    71	    .map(parseSeatId)
    72	    .filter((seat): seat is { row: number; column: number } => seat !== null)
    73	    .sort((a, b) => a.row - b.row || a.column - b.column);
    74	
    75	  const tickets: Ticket[] = [];
    76	  const couches = new Set<number>();
    77	  for (const { row, column } of seats) {
    78	    if (row === COUCH_ROW) {
    79	      // Couches cover columns 1–2, 3–4, … 23–24, so a couch starts at an odd column.
    80	      const start = column % 2 === 1 ? column : column - 1;
    81	      if (couches.has(start)) {
    82	        continue;
    83	      }
    84	      couches.add(start);
    85	      tickets.push({
    86	        ids: [seatId(row, start), seatId(row, start + 1)],
    87	        row,
    88	        seat: `Couch ${start}-${start + 1}`,
    89	        price: COUCH_PRICE,
    90	      });
    91	    } else {
    92	      tickets.push({
    93	        ids: [seatId(row, column)],
    94	        row,
    95	        seat: String(column),
    96	        price: seatPrice(row),
    97	      });
    98	    }
    99	  }
   100	  return tickets;
   101	}
   102	
   103	/** Keeps the booking in progress in `sessionStorage`, so it survives a reload. */
   104	@Injectable({ providedIn: 'root' })
   105	export class BookingService {
   106	  /** The booking in progress, or null when there is none or it cannot be read. */
   107	  load(): Booking | null {
   108	    const raw = sessionStorage.getItem(STORAGE_KEY);
   109	    if (raw === null) {
   110	      return null;
   111	    }
   112	    try {
   113	      return JSON.parse(raw) as Booking;
   114	    } catch {
   115	      return null;
   116	    }
   117	  }
   118	
   119	  save(booking: Booking): void {
   120	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
   121	  }
   122	
   123	  clear(): void {
   124	    sessionStorage.removeItem(STORAGE_KEY);
   125	  }
   126	
   127	  /**
   128	   * The seats of the booking in progress when it belongs to the screening and is unpaid,
   129	   * otherwise none.
   130	   */
   131	  seatsFor(screeningId: string | undefined): string[] {
   132	    const booking = this.load();
   133	    return booking !== null &&
   134	      booking.paid === undefined &&
   135	      booking.screeningId === Number(screeningId)
   136	      ? booking.seats
   137	      : [];
   138	  }
   139	
   140	  /** Changes some fields of the booking in progress, keeping the others. Does nothing without one. */
   141	  update(changes: Partial<Booking>): void {
   142	    const booking = this.load();
   143	    if (booking !== null) {
   144	      this.save({ ...booking, ...changes });
   145	    }
   146	  }
   147	
   148	  /**
   149	   * Called once the seat map of a screening has loaded: keeps the booking when it is unpaid and
   150	   * belongs to the screening, otherwise replaces it with an empty booking for the screening.
   151	   */
   152	  openFor(screeningId: number): void {
   153	    const booking = this.load();
   154	    if (booking === null || booking.paid !== undefined || booking.screeningId !== screeningId) {
   155	      this.save({ screeningId, seats: [] });
   156	    }
   157	  }
   158	}
   159	
   160	/**
   161	 * Lets a route with a `:id` parameter be entered only with an unpaid booking in progress for
   162	 * that screening that has at least one seat; otherwise redirects to `/` (section 3.1).
   163	 */
   164	export const bookingGuard: CanActivateFn = (route: ActivatedRouteSnapshot) => {
   165	  const booking = inject(BookingService).load();
   166	  const allowed =
   167	    booking !== null &&
   168	    booking.paid === undefined &&
   169	    booking.seats.length > 0 &&
   170	    booking.screeningId === Number(route.paramMap.get('id'));
   171	  return allowed || inject(Router).createUrlTree(['/']);
   172	};
   173	
   174	/** Lets the confirmation be entered only with a paid booking; otherwise redirects to `/` (section 3.1). */
   175	export const confirmationGuard: CanActivateFn = () => {
   176	  const booking = inject(BookingService).load();
   177	  return booking?.paid !== undefined || inject(Router).createUrlTree(['/']);
   178	};
