cd /workspace/project/dist/apps/cinescope/browser && node -e '
const fs=require("fs");const f=fs.readdirSync(".").find(x=>/^styles-.*\.css$/.test(x));
const css=fs.readFileSync(f,"utf8");
const re=/([^{}]*)\{([^{}]*)\}/g;let m;
while((m=re.exec(css))){const s=m[1].trim();if(/seat|couch|swatch|hover|focus|button|aisle|row/.test(s))console.log(s.slice(0,200),"=>",m[2].slice(0,160));}
'

cd /workspace/project/dist/apps/cinescope/browser && node -e '
const fs=require("fs");const f=fs.readdirSync(".").find(x=>/^main-.*\.js$/.test(x));
const js=fs.readFileSync(f,"utf8");
const idx=[...js.matchAll(/data-state/g)].map(m=>m.index);
console.log("hits",idx.length);
for(const i of idx.slice(0,12)) console.log(js.slice(Math.max(0,i-120),i+200).replace(/\n/g," "), "\n---");
'

