33	function createApi() {
34	  return {
35	    getMovies: vi.fn((): Observable<Movie[]> => of(movies)),
36	    getScreeningsByDate: vi.fn((date: string): Observable<Screening[]> => of(screenings.filter((s) => s.date === date))),
37	  };
38	}
