40	async function settle(fixture: ComponentFixture<Host>): Promise<void> {
41	  for (let i = 0; i < 3; i++) {
42	    await new Promise((resolve) => setTimeout(resolve, 0));
43	    fixture.detectChanges();
44	  }
45	}
