47	function query(fixture: ComponentFixture<Host>, testId: string): HTMLElement | null {
48	  return (fixture.nativeElement as HTMLElement).querySelector(`[data-testid="${testId}"]`);
49	}
50	
51	function queryAll(fixture: ComponentFixture<Host>, testId: string): HTMLElement[] {
52	  return Array.from((fixture.nativeElement as HTMLElement).querySelectorAll<HTMLElement>(`[data-testid="${testId}"]`));
53	}
54	
55	async function open(url: string, api: ReturnType<typeof createApi>): Promise<ComponentFixture<Host>> {
56	  TestBed.configureTestingModule({
57	    providers: [
58	      provideZonelessChangeDetection(),
59	      provideRouter([{ path: '', component: MovieList }]),
60	      provideNativeDateAdapter(),
61	      { provide: ApiService, useValue: api },
62	    ],
63	  });
64	  const fixture = TestBed.createComponent(Host);
65	  fixture.detectChanges();
66	  await TestBed.inject(Router).navigateByUrl(url);
67	  await settle(fixture);
68	  return fixture;
69	}
70	
71	describe('MovieList', () => {
72	  it('shows today by default with one card per movie with a screening, buttons ordered by time', async () => {
73	    const fixture = await open('/', createApi());
74	
75	    const cards = queryAll(fixture, 'movie-card');
76	    expect(cards.map((card) => card.dataset['movieId'])).toEqual(['1']);
77	    expect(query(fixture, 'movie-title')?.textContent?.trim()).toBe('The Silent Harbor');
78	    expect(query(fixture, 'movie-genre')?.textContent?.trim()).toBe('Drama');
79	    expect(query(fixture, 'movie-runtime')?.textContent?.trim()).toBe('128 min');
80	    expect(query(fixture, 'movie-format')?.textContent?.trim()).toBe('PL subtitles');
81	
82	    const buttons = queryAll(fixture, 'screening-button');
83	    expect(buttons.map((button) => button.textContent?.trim())).toEqual(['16:00', '19:30']);
84	    expect(buttons.map((button) => button.dataset['screeningId'])).toEqual(['2', '1']);
85	  });
86	
87	  it('shows the five day buttons with Today selected by default', async () => {
88	    const fixture = await open('/', createApi());
89	
90	    const days = queryAll(fixture, 'day-button');
91	    expect(days.length).toBe(5);
92	    expect(days[0].textContent?.trim()).toBe('Today');
93	    expect(days[0].dataset['selected']).toBe('true');
94	    expect(days.slice(1).every((day) => day.dataset['selected'] === 'false')).toBe(true);
95	    expect(days.map((day) => day.dataset['date'])[0]).toBe(today);
96	    expect(query(fixture, 'date-picker')).not.toBeNull();
97	  });
98	
99	  it('selects the day from the URL and shows only that day', async () => {
100	    const fixture = await open(`/?date=${tomorrow}`, createApi());
101	
102	    const cards = queryAll(fixture, 'movie-card');
103	    expect(cards.map((card) => card.dataset['movieId'])).toEqual(['2']);
104	    expect(queryAll(fixture, 'screening-button').map((b) => b.textContent?.trim())).toEqual(['20:00']);
105	    expect(queryAll(fixture, 'day-button').every((day) => day.dataset['selected'] === 'true')).toBe(false);
106	  });
107	
108	  it('selects today for an invalid or past date', async () => {
109	    const past = toIsoDate(addDays(startOfDay(new Date()), -3));
110	    for (const url of ['/?date=2026-02-30', '/?date=not-a-date', `/?date=${past}`]) {
111	      const fixture = await open(url, createApi());
112	      expect(queryAll(fixture, 'day-button')[0].dataset['selected']).toBe('true');
113	      expect(queryAll(fixture, 'movie-card').length).toBe(1);
114	      TestBed.resetTestingModule();
115	    }
116	  });
117	
118	  it('shows the empty message when no movie has a screening on the day', async () => {
119	    const fixture = await open('/?date=2099-01-01', createApi());
120	
121	    expect(query(fixture, 'movies-empty')?.textContent?.trim()).toBe('No screenings on this day');
122	    expect(queryAll(fixture, 'movie-card').length).toBe(0);
123	  });
124	
125	  it('shows the loading indicator and no cards while the request is in flight', async () => {
126	    const api = createApi();
127	    api.getMovies.mockImplementation(() => new Observable<Movie[]>(() => undefined));
128	    const fixture = await open('/', api);
129	
130	    expect(query(fixture, 'movies-loading')?.textContent?.trim()).toBe('Loading…');
131	    expect(queryAll(fixture, 'movie-card').length).toBe(0);
132	  });
133	
134	  it('shows the error with Retry, which re-issues the request', async () => {
135	    const api = createApi();
136	    api.getMovies.mockImplementationOnce(() => throwError(() => new Error('network')));
137	    const fixture = await open('/', api);
138	
139	    expect(query(fixture, 'movies-error')?.textContent?.trim()).toBe('Failed to load movies');
140	    expect(queryAll(fixture, 'movie-card').length).toBe(0);
141	
142	    (query(fixture, 'movies-retry-button') as HTMLButtonElement).click();
143	    await settle(fixture);
144	
145	    expect(api.getMovies).toHaveBeenCalledTimes(2);
146	    expect(query(fixture, 'movies-error')).toBeNull();
147	    expect(queryAll(fixture, 'movie-card').length).toBe(1);
148	  });
149	});
